from pathlib import Path

def read(i):return (Path('items')/(i+'.md')).read_text()
def save(i,s):(Path('items')/(i+'.md')).write_text(s)
def swap(s,a,b):assert a in s,a[:90];return s.replace(a,b,1)
i='def-nrqm-driven-dynamics-framework-driven-model';s=read(i);s=swap(s,r'\mu^{H_{0}}_{\varphi_{j}(t)}',r'\mu^{H_{0}}_{\psi(t)}');save(i,s)
i='def-nrqm-driven-dynamics-framework-adiabatic-protocol';s=read(i);s=s.replace('$s\\mapsto TH(s)$','$s\\mapsto TH(s)/\\hbar$');save(i,s)
i='pthm-nrqm-driven-dynamics-first-order-transition-amplitude';s=read(i);s=s.replace(r'e^{i\Delta\tau/\hbar}\langle U(t,s)\varphi_{i},\varphi_{j}\rangle',r'e^{iE_j\tau/\hbar}\langle U(t,s)\varphi_{i},\varphi_{j}\rangle');a=s.index('2.1 [Probability error]');b=s.index('\n\n3.1',a);s=s[:a]+r'''2.1 [Probability error for transition and survival] By [F2], $p_{ji}=|A_{ji}|^2$, and step1.1 gives $A_{ji}=b_{ji}+R$, where $b_{ji}=\delta_{ij}+A^{(1)}$ and $|R|\le\varepsilon$. The identity $|b+R|^2-|b|^2=2\operatorname{Re}(R\overline b)+|R|^2$ therefore gives $|p_{ji}-|b_{ji}|^2|\le2|b_{ji}|\varepsilon+\varepsilon^2$. For $i\ne j$, $b_{ji}=A^{(1)}$, giving the displayed transition bound; for $i=j$, $b_{ii}=1+A^{(1)}$ and $|b_{ii}|\le1+|A^{(1)}|$, giving the displayed survival bound. No diagonal term is dropped. This proves (c). [step 1.1, F2, F3, algebra]''' +s[b:];s=s.replace('step1.1','step 1.1');save(i,s)
i='pthm-nrqm-driven-dynamics-bounded-norm-propagator';s=read(i);s=s.replace('the bound on the difference of the Born outcome probabilities computed with the exact and the truncated propagator','the bound comparing exact Born probabilities to unnormalized truncated quadratic estimates');s=s.replace('*Outcome-law error of the truncation.*','*Error of the unnormalized truncated quadratic estimate.*');s=swap(s,r'\le 2\,\bigl\|R_{N}(t,s)\bigr\|\le 2\,e^{K\tau}',r'\le (1+\|\sum_{n=0}^NU_n(t,s)\|)\,\|R_N(t,s)\|\le 2\,e^{K\tau}');s=s.replace('where the truncated law is the un-normalized quadratic form','where the truncated quantity is the unnormalized quadratic form').replace('whose norm is at most $e^{K\\tau}$;','whose norm is at most $e^{K\\tau}$. It is an approximation to the normalized exact Born law and need not itself be a probability law;');s=s.replace('for all $s,t\\in I$ and all $N$ ([[lem-nrqm-controlled-dynamics-dyson-truncation-bound]] clause (b)).','for all $s,t\\in I$ and all $N$, and the same actual self-adjoint hypotheses give the stronger $\\|R_N(t,s)\\|\\le(K\\tau)^{N+1}/(N+1)!$ ([[lem-nrqm-controlled-dynamics-dyson-truncation-bound]] clause (b)).');a=s.index('2.1 [Error of the truncated outcome law]');b=s.index('\n\n3.1',a);s=s[:a]+r'''2.1 [Error of the unnormalized truncated estimate] Let $S_N=\sum_{n=0}^NU_n(t,s)$, $u=U(t,s)\psi(s)$ and $v=S_N\psi(s)$ for a unit initial vector. Then $\|u\|=1$, $\|v\|\le\|S_N\|\le\sum_{n=0}^N(K\tau)^n/n!\le e^{K\tau}$ by [F1], and $\|u-v\|\le\|R_N\|$. For the spectral projection $Q=E_A(B)$, the exact Born probability is $\|Qu\|^2$ while $\|Qv\|^2$ is the stated unnormalized quadratic estimate. Their difference equals $\langle Q(u-v),Qu\rangle+\langle Qv,Q(u-v)\rangle$; Cauchy-Schwarz and contraction of $Q$ bound its absolute value by $(1+\|S_N\|)\|R_N\|\le(1+e^{K\tau})\|R_N\|$. Crucially [F2] supplies the stronger unitary remainder $\|R_N\|\le(K\tau)^{N+1}/(N+1)!$, so the result is at most $2e^{K\tau}(K\tau)^{N+1}/(N+1)!$, preserving the advertised final bound. For $N=1$ it is at most $e^{K\tau}(K\tau)^2$, and hence also the stated looser $2e^{K\tau}(K\tau)^2$. At $K\tau=0$ both quantities coincide. No unit norm or density interpretation is assigned to the truncated vector. This proves (d). [step 1.1, step 1.2, F1, F2, F3, F4, algebra]''' +s[b:];save(i,s)
i='pthm-nrqm-driven-dynamics-common-domain-propagator';s=read(i);s=swap(s,'$0\\le s\\le t\\le b-a$ understood on $I$','$a\\le s\\le t\\le b$ on $I$');s=swap(s,'depends only on $I$ and $L$','is independent of the endpoints and depends on the actual graph equivalence of $Y$ with $D(H(t)/\\hbar)$ as well as $I$ and $L/\\hbar$');s=s.replace('These are exactly the hypotheses','These are exactly the hypotheses');needle='This is clause (a). [F1, F3, given]';replacement=r'''For explicit dependence, put $K(t)=A(t)-i:Y\to\mathfrak H$, $M=\sup_t\|K(t)^{-1}\|_{\mathfrak H\to Y}$, $N=\sup_t\|K(t)\|_{Y\to\mathfrak H}$, and $L_A=L/\hbar$. The bounded inverse and local Neumann construction in [F1], proof2.1, shows $M,N<\infty$ on compact $I$, without a further hypothesis. Its proof3.1 bounds the frozen products and limiting evolution in $Y$ by a uniform constant controlled by $MN e^{L_A M(b-a)}$, with the endpoint graph conversions described there. Thus the genuine family-dependent graph constants, rather than $I,L$ alone, control $C_I$. This is clause (a). [F1, F3, given]''';s=swap(s,needle,replacement.replace('proof2.1','proof 2.1').replace('proof3.1','proof 3.1'));save(i,s)
i='pthm-nrqm-driven-dynamics-circular-drive-exact-rabi';s=read(i);s=s.replace('$t\\in I=[a,b]$','$t\\in I=[t_-,t_+]$');s=swap(s,'the drive inverts the population fully at','when $\\Omega_1\\ne0$, the drive inverts the population fully at');s=swap(s,r'\psi_{R}(t)=e^{-i\tau H_{R}/\hbar}e_{\uparrow}',r'\psi_R(t)=e^{i\omega s/2}e^{-i\tau H_R/\hbar}e_{\uparrow}, since $R(s)e_{\uparrow}=e^{i\omega s/2}e_{\uparrow}$. This initial phase has modulus one and leaves populations unchanged');s=s.replace('the first zero of the sine factor occurs at $\\tau=\\pi/|\\Omega_{1}|$','for $\\Omega_1\\ne0$ the first full inversion occurs at $\\tau=\\pi/|\\Omega_{1}|$');save(i,s)
i='lem-nrqm-driven-dynamics-two-level-rotating-frame';s=read(i);s=s.replace('For the linear family it is that constant matrix plus','For the linear family it is its averaged constant matrix $A$ (with transverse coefficient $\\Omega_1/2$) plus');save(i,s)
i='ex-nrqm-driven-dynamics-circular-drive-exact-populations';s=read(i);s=s.replace(r'=e^{\mp 2i\theta}\sigma_{\pm}',r'=e^{\pm 2i\theta}\sigma_{\pm}');s=s.replace('the declared model precesses about the $\\sigma_{z}$ axis at the splitting frequency $\\omega_{0}$;','the general coherence transforms by this phase at the splitting frequency $\\omega_0$, while the specified initial up state has both transverse coherences zero;');s=s.replace('and the transverse coherences rotate with that phase;','so the phase identity holds for every initial vector, while for the specified up state the initial and evolved transverse coherences both vanish;');save(i,s)
i='ex-nrqm-driven-dynamics-ammonia-two-level-resonance';s=read(i);s=s.replace(r'\hbar\Omega_{1}\tau/4=\pi/2',r'\Omega_{1}\tau/4=\pi/2').replace('the Rabi population of the up-state is','the down-population of the initial up-state is');save(i,s)
i='pthm-nrqm-driven-dynamics-finite-adiabatic-leakage';s=read(i);s=s.replace(r'(TH(s)+iK(s))',r'(TH(s)/\hbar+iK(s))').replace(r'(-iTH+K)',r'(-iTH/\hbar+K)');s=swap(s,r'C:=2\sup_{s\in[0,1]}\|X(s)\|+\int_{0}^{1}\bigl(\|X\x27(s)\|+\|K(s)\|\,\|X(s)\|\bigr)\,ds<\infty,',r'NEVER') if False else s
s=s.replace(r'C:=2\sup_{s\in[0,1]}\|X(s)\|+\int_{0}^{1}',r'C:=\hbar\Bigl(2\sup_{s\in[0,1]}\|X(s)\|+\int_{0}^{1}').replace(r'\,ds<\infty,$$',r'\,ds\Bigr)<\infty,$$');a=s.index('[F1] **Finite gapped adiabatic supplier.**');b=s.index('\n\n[F2]',a);s=s[:a]+r'''[F1] **Finite gapped adiabatic supplier and physical scaling.** Applied to the normalized generator $A=H/\hbar$, [[thm-nrqm-controlled-dynamics-finite-gapped-adiabatic-estimate]] gives $P\in C^2$, $K=[P',P]$, $[K,P]=P'$ and a $C^1$ Hermitian $X_A$ with $[A,X_A]=K$. Its modified propagator solves $iU_A'=(TA+iK)U_A$, intertwines $P$, and its leakage constant is $C_A=2\sup\|X_A\|+\int_0^1(\|X_A'\|+\|K\|\|X_A\|)$. Put $X=X_A/\hbar$; then $[H,X]=K$ and $C_A=\hbar(2\sup\|X\|+\int_0^1(\|X'\|+\|K\|\|X\|))$. The normalized protocol generator $TH/\hbar$ has the unitary Dyson propagator ([[thm-nrqm-controlled-dynamics-norm-dyson-series-and-uniqueness]]), which solves exactly the physical equation $i\hbar U_T'=THU_T$.''' +s[b:];s=s.replace('The family $H$ and the coherently followed uniformly gapped cluster satisfy the hypotheses of [F1], so [F1] gives','The family $A=H/\\hbar$ is C² Hermitian with the same coherently followed spectral projections and gap $g/\\hbar>0$. Applying [F1] and putting $X=X_A/\\hbar$ gives');s=s.replace('with the displayed finite constant for every','with the displayed physical constant $C=C_A$ for every');save(i,s)
